"""
    Allows you to replace everything you need in one function using two lists.
    :param text:
    :param old:
    :param new:
    :return:
    """
def hyper_replace(text: Any, old: list, new: list) -> object {
    msg = str(text);
    for (x, y) in zip(old, new) {
        msg = str(msg).replace(x, y);
    }
    return msg;
}

